from collections import defaultdict

by_month = defaultdict(lambda: {"revenue": 0.0, "orders": set(), "units": 0})
for row in dataset.rows:
    m = row["order_date"][:7]
    by_month[m]["revenue"] += float(row["revenue"] or 0)
    by_month[m]["orders"].add(row["order_id"])
    by_month[m]["units"] += int(row["units"] or 0)

result = [
    {
        "bulan": m,
        "revenue": round(by_month[m]["revenue"], 2),
        "jumlah_order": len(by_month[m]["orders"]),
        "units": by_month[m]["units"],
    }
    for m in sorted(by_month)
]
